-- ADR-0026: kind=thesis 두 개에 novelty·what_market_misses·lag_months·first_signal·quiet_check 를 채운다 (0029 적용 뒤 실행)
select ideas.put_theses($wsj$[{"thesis_key": "memory_inference_rerating_2026", "title": "에이전트 추론이 토큰당 메모리를 늘려 메모리 3사의 이익 체제를 바꾼다", "statement": "AI 의 쓰임이 '한 번 답하는 챗' 에서 '오래 도는 에이전트' 로 옮겨가면 질문당 출력 토큰(2H24 이후 연 5배↑, 3~4만 토큰)과 세션당 KV 캐시 상주량이 함께 늘고, 그 메모리는 가속기 HBM 에서 끝나지 않고 CPU DRAM(CPU:GPU 1:4~1:8 → 1:1, Vera 1.5TB LPDDR5X) 과 컨텍스트 저장용 SSD(CMX 랙당 ~9,600TB) 로 계층을 이루며 번진다. 공급은 세대 전환·공정 전환에 묶여 2027년까지 비트 할당이 모자라고(SK hynix: HBM 요청이 공급의 2배, DRAM·HBM 2029년까지 매진; Vera Rubin SOCAMM 용량 반감), 그 결과 메모리 가격 체제가 바뀌어 SK hynix·삼성전자·Micron 의 이익과 배수가 함께 오른다(리레이팅). 하류로는 적층·검사 장비와 서버 기판(삼성전기 FC-BGA)까지 같은 수요가 닿는다. 시장은 HBM 은 이미 반영했지만 '추론 → 일반 DRAM·NAND 로 번지는 2차 파동' 과 그 지속 기간은 덜 반영했다는 것이 이 테제의 내기다.", "ecosystem": "hbm", "chain": [{"node": "demand_driver:long_context", "claim": "질문당 출력 토큰이 2H24 이후 연 5배 넘게 늘어 3~4만 토큰 (Nvidia 공개 자료)", "evidence": [{"url": "https://www.trendforce.com/insights/ai-inference-drives-memory-demand", "title": "TrendForce — AI inference drives memory demand", "date": "2026-07-07", "kind": "trade_press"}]}, {"node": "demand_driver:kv_cache_residency", "claim": "KV 캐시가 HBM → CPU DRAM → SSD 계층으로 오프로딩된다 (Dynamo 2025-03, CMX 2026-01 랙당 ~9,600TB)", "evidence": [{"url": "https://www.trendforce.com/insights/ai-inference-drives-memory-demand", "title": "TrendForce", "date": "2026-07-07", "kind": "trade_press"}]}, {"node": "req:cpu_memory_per_rack", "claim": "에이전트 AI 는 CPU:GPU 비를 1:1 로 끌어올리고 Vera CPU 는 1.5TB LPDDR5X 를 단다", "evidence": [{"url": "https://www.trendforce.com/insights/ai-inference-drives-memory-demand", "title": "TrendForce", "date": "2026-07-07", "kind": "trade_press"}]}, {"node": "bottleneck:dram_bit_supply", "claim": "2027 LPDRAM 할당 부족으로 Vera Rubin SOCAMM 용량이 반감됐다는 보도 — 수요가 아니라 공급이 모자람", "evidence": [{"url": "https://www.trendforce.com/insights/ai-inference-drives-memory-demand", "title": "TrendForce", "date": "2026-07-07", "kind": "trade_press"}]}, {"node": "bottleneck:hbm_bit_supply", "claim": "SK hynix 3Q26: 고객 HBM 요청이 공급의 2배, DRAM·HBM 2029년까지 매진", "evidence": [{"url": "https://www.eetimes.com/sk-hynix-reports-record-q3-results-driven-by-ai-memory-surge/", "title": "EE Times — SK hynix record Q3", "date": "2026-10-28", "kind": "trade_press"}]}, {"node": "company:skhynix", "claim": "비트 부족 → 계약가 상승 → 이익률과 배수가 함께 오르는 리레이팅 (추론; 2023~24 HBM 사례의 2차 파동)", "evidence": []}], "drivers": [{"id": "output_tokens_per_query", "label": "질문당 평균 출력 토큰", "metric": "tokens", "latest": {"value": 35000, "as_of": "2026-07-07", "source": "Nvidia 공개 자료 (TrendForce 인용)"}, "threshold": "연 3배 미만으로 둔화하면 약화", "direction": "up"}, {"id": "cpu_gpu_ratio_agentic", "label": "에이전트 랙의 CPU:GPU 비", "metric": "ratio", "latest": {"value": "1:1 (전망)", "as_of": "2026-07-07", "source": "TrendForce"}, "threshold": "1:4 로 되돌아가면 약화", "direction": "up"}, {"id": "server_dram_contract_price", "label": "서버 DRAM 계약가 (분기)", "metric": "QoQ %", "latest": {"value": "급등 (수치 미확인)", "as_of": "2026-07-07", "source": "TrendForce 2Q26 보고 요약"}, "threshold": "두 분기 연속 하락이면 반증", "direction": "up"}, {"id": "hbm_demand_supply_ratio", "label": "HBM 요청/공급 비 (SK hynix 발언)", "metric": "x", "latest": {"value": 2, "as_of": "2026-10-28", "source": "SK hynix 3Q26 컨콜"}, "threshold": "1.2 이하로 내려가면 약화", "direction": "up"}, {"id": "socamm_allocation", "label": "Vera Rubin SOCAMM 용량 할당", "metric": "GB", "latest": {"value": "반감 보도", "as_of": "2026-07-07", "source": "TrendForce"}, "threshold": "원래 사양 복원이면 공급 압박 완화", "direction": "down"}], "beneficiaries": [{"company": "company:skhynix", "role": "primary", "basis": "HBM 1위 + DRAM·NAND 전 계층", "size_band": "mega", "rerating": {"from": "P/B 2배대·P/E 10배 안팎(사이클 피크 할인)", "to": "구조적 성장주 배수", "why": "추론 수요가 사이클이 아니라 체제로 받아들여질 때"}}, {"company": "company:samsung", "role": "primary", "basis": "DRAM·NAND 최대 생산, HBM4 추격", "size_band": "mega", "rerating": {"from": "P/B 1배대", "to": "DRAM 가격 체제 반영", "why": "일반 DRAM 비트 부족은 HBM 2위도 수혜"}}, {"company": "company:mu", "role": "primary", "basis": "미국 상장 메모리 순수 노출", "size_band": "mega", "rerating": {"from": "사이클 P/E", "to": "체제 P/E", "why": "같은 논리"}}, {"company": "company:semco", "role": "secondary", "basis": "AI 서버 FC-BGA·MLCC — 랙당 CPU·메모리가 늘면 기판 면적·층수도 는다", "size_band": "large", "rerating": {"from": "", "to": "", "why": "2차 파동의 하류 — 근거 쌓이면 승격"}}], "losers": [{"node": "component:server_dram_lpdram", "why": "메모리를 많이 쓰는 비-AI 서버·스마트폰 OEM 은 원가 압박 (삼성 MX·PC OEM) — 테제가 맞을수록 이들의 마진이 눌린다"}], "falsifiers": [{"what": "서버 DRAM 계약가가 두 분기 연속 하락", "metric": "TrendForce 서버 DRAM 계약가 QoQ", "threshold": "< 0% 두 분기", "due": "2027-04-30"}, {"what": "SK hynix·Micron 이 HBM 공급 과잉·가격 하락을 가이던스에 언급", "metric": "컨콜 발언", "threshold": "공급 > 수요", "due": "2027-02-28"}, {"what": "질문당 출력 토큰 증가율이 연 3배 미만으로 둔화 (Nvidia·OpenAI 공개 수치)", "metric": "tokens/query YoY", "threshold": "< 3x", "due": "2027-06-30"}], "stage": 1, "stage_reason": "동인(출력 토큰·CPU:GPU 비·KV 캐시 계층)은 움직이고 공급 부족도 보이지만(1단계 충족), 2차 파동(일반 DRAM·NAND 가격 체제)의 숫자는 아직 분기 계약가로 확인 중", "kind": "thesis", "novelty": "new_technology", "novelty_reason": "에이전트 추론·긴 컨텍스트·KV 캐시 상주는 온톨로지에 없던 수요 동인(p20261029 에 추가). HBM 2023 과 닮았지만, 부족이 HBM 밖(서버 DRAM·LPDDR·컨텍스트 SSD)으로 번지는 2차 파동은 전례가 없다.", "what_market_misses": "시장은 HBM 매진은 읽었지만, 에이전트 추론이 토큰당 메모리를 비트 성장보다 빠르게 늘려 부족이 HBM 밖(서버 DRAM·LPDDR5X·KV 캐시 SSD)으로 번지고 메모리 3사의 배수가 사이클 밴드를 벗어나는 것은 덜 읽는다.", "lag_months": 12, "first_signal": {"metric": "서버 DRAM 계약가 QoQ 와 LPDDR5X 서버 할당 비중", "where": "TrendForce 분기 계약가 · SK hynix/Micron 컨콜", "expected_by": "2027-01"}, "quiet_check": {"as_of": "2026-10-29", "companies": [{"company": "company:skhynix", "px_6m_pct": null, "px_12m_pct": null, "note": "KR 가격 맥락 미수집"}, {"company": "company:samsung", "px_6m_pct": null, "px_12m_pct": null, "note": "KR 가격 맥락 미수집"}, {"company": "company:mu", "px_6m_pct": null, "px_12m_pct": null, "note": "v_price_context 에 없음"}, {"company": "company:semco", "px_6m_pct": null, "px_12m_pct": null, "note": "KR 가격 맥락 미수집"}], "verdict": "unmeasured", "note": "v_price_context 가 미국 350종목뿐 — KR·MU 가격 맥락 수집이 선행 과제(K-13)"}, "benchmark": "hbm_2023", "model": "claude-fable-5-1", "method": "session"}, {"thesis_key": "test_intensity_stacking_2026", "title": "적층이 늘수록 칩당 테스트·번인 시간이 늘어 테스트 장비·소모품이 메모리 비트보다 빨리 큰다", "statement": "HBM 이 12단·16단으로, 가속기가 2.5D/3D 로 쌓이면 불량 다이 하나가 패키지 전체를 버리게 되므로 적층 전 KGD 검사와 적층 후 KGSD·번인 시간이 비트 성장보다 빠르게 는다. 대만 테스트 소모품사의 9월 매출이 그것을 먼저 보여 준다 — WinWay(소켓) +88%, MPI(프로브카드) +82%, Chroma(ATE) +206%. 메모리 테스터 시장은 2025년 $21억(Advantest 61%)이고, SK hynix 가 HBM 요청이 공급의 2배라고 밝힌 뒤 HBM4 12단 수율·발열 문제가 이어진다는 보도는 검사 강도를 더 올린다. 2023~24 HBM 사례에서 메모리사 다음에 장비사(한미반도체 6배)가 왔듯, 이번엔 테스트·번인 고리(테크윙·ISC·리노공업·FormFactor·Cohu·Aehr)가 2차 파동이라는 내기다.", "ecosystem": "hbm", "chain": [{"node": "req:hbm_stack", "claim": "12단·16단 적층, HBM4 12단 수율·발열 문제 지속 보도", "evidence": [{"url": "https://news.google.com/rss/articles/CBMirgFBVV95cUxOaENzeGF6NkFYUU9Tc2JYc0lSZnBIUkE5THVXWndhT0ExSV9oc3ZJLXRVRkxkdXBLT09xNHA5eTdxamNfcnVUYWNnd3ZXWExOcURhWW9aU1c1YjVIVTMxaWJObkl3dkdHRjRkbkR2X0EzQmZRMUFMREIxaVYzczFIdUZCMVBYazRPaGxzWjFwNVAzcVVaZURiRDdNMWVoN2Q5c0NCUjUtRmE5TEhuUXc?oc=5", "title": "Vera Rubin HBM4 보도", "date": "2026-10-27", "kind": "news"}]}, {"node": "bottleneck:hbm_kged", "claim": "적층 전 KGD·적층 후 KGSD 검사가 병목 — 불량 1개가 패키지 전체를 버림", "evidence": []}, {"node": "component:memory_test_socket", "claim": "대만 소모품사 9월 매출: WinWay +88%, MPI +82%, Chroma ATE +206%", "evidence": [{"url": "https://mops.twse.com.tw/mops/#/web/t146sb05?companyId=6515", "title": "WinWay 월매출", "date": "2026-10-10", "kind": "official"}]}, {"node": "equipment:memory_ate", "claim": "메모리 테스터 시장 2025 $21억, Advantest 61%", "evidence": [{"url": "https://xenospectrum.com/en/china-memory-testing-hbm-equipment/", "title": "memory tester market", "date": "2026-10-01", "kind": "trade_press"}]}, {"node": "company:techwing", "claim": "테스트·번인 장비·소모품사의 2차 파동 (추론; 2024 한미반도체 사례)", "evidence": []}], "drivers": [{"id": "tw_test_consumables_yoy", "label": "대만 테스트 소모품·ATE 월매출 YoY (WinWay·MPI·Chroma)", "metric": "% YoY", "latest": {"value": "+88 / +82 / +206", "as_of": "2026-09-30", "source": "MOPS 9월 월매출"}, "threshold": "두 달 연속 +20% 미만이면 